import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { AgreementRequiredError, POLICY_DOCUMENTS, isAgreementRequired, parsePolicyVersions, throwIfAgreementRequired } from "./policies.js";
import type { AgreementRequired } from "./policies.js";

// The runtime list must match the API's OpenAPI document (regenerated by `pnpm sdk`), in order.
const openapi = JSON.parse(readFileSync(new URL("../openapi.json", import.meta.url), "utf8")) as {
  components: { schemas: Record<string, { properties: Record<string, { enum?: string[] }> }> };
};

const body: AgreementRequired = {
  error: "agreement_required",
  message: "Agree to the terms of service (version 2) to post, comment and vote again.",
  document: "terms",
  version: 2,
  summary: "Clearer rules on self-promotion.",
  url: "https://yakfeed.com/policies/terms/2",
  pending: [],
};

describe("policy versions", () => {
  it("lists the documents the API has, in order", () => {
    expect([...POLICY_DOCUMENTS]).toEqual(openapi.components.schemas.PolicyVersion!.properties.document!.enum);
  });

  it("types agreement_required as an error", () => {
    expect(isAgreementRequired(body)).toBe(true);
    expect(isAgreementRequired({ error: "forbidden", message: "no" })).toBe(false);
    expect(() => throwIfAgreementRequired({ error: body })).toThrow(AgreementRequiredError);
    try {
      throwIfAgreementRequired({ error: body });
    } catch (e) {
      expect(e).toMatchObject({ code: "agreement_required", document: "terms", version: 2, url: body.url });
    }
    const fine: { data?: number; error?: unknown } = { data: 1 };
    expect(throwIfAgreementRequired(fine)).toBe(fine);
  });

  it("reads the version header", () => {
    expect(parsePolicyVersions("terms=2, privacy=1, rules=3")).toEqual({ terms: 2, privacy: 1, rules: 3 });
    expect(parsePolicyVersions(null)).toEqual({});
    expect(parsePolicyVersions("nonsense, terms=x")).toEqual({});
  });
});
